def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Identify full horizontal and vertical lines of the dominant repeated symbol
    # that serve as dividers, recoloring them to 2.
    for r in range(h):
        if len(set(grid[r])) == 1:
            for c in range(w): out[r][c] = 2
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            for r in range(h): out[r][c] = 2
    return out
